function toMin(t){ if(!t) return null; const m=/^(\d{1,2}):(\d{2})$/.exec(String(t).trim()); if(!m) return null; return (+m[1])*60 + (+m[2]); }
const rows = $input.all().map(i => i.json);
const onTime=[], late=[], absent=[];
for (const r of rows){
  const name=r.fullName; const exp=r.expectedAt; const arr=r.arrivedAt;
  const txt=(r.entryText||'').toUpperCase();
  if (txt==='FALTA'){ absent.push(name); continue; }
  if (txt && txt!=='CONTEO'){ continue; } // descanso/vacaciones/pago: no se juzga
  if (r.schedStatus && r.schedStatus!=='WORKING'){ continue; } // no le tocaba
  if (!arr){ absent.push(name); continue; }
  const e=toMin(exp), a=toMin(arr);
  if (e===null || a===null){ onTime.push(name); continue; }
  const ml=a-e;
  if (ml<=14) onTime.push(name); else if (ml<30) late.push(name+' (+'+ml+'m)');
  // >=30 = permiso/entrada tarde: no es retardo ni falta
}
const d = new Date().toLocaleDateString('es-MX', { day: 'numeric', month: 'short', timeZone: 'America/Monterrey' });
let text = '📊 *Cierre de hoy — ' + d + '*\n';
text += '✅ ' + onTime.length + ' a tiempo' + (onTime.length? ' ('+onTime.join(', ')+')':'') + '\n';
text += '🕐 ' + late.length + ' retardos' + (late.length? ' ('+late.join(', ')+')':'') + '\n';
text += '❌ ' + absent.length + ' faltas' + (absent.length? ' ('+absent.join(', ')+')':'');
return [{ json: { text } }];
